import { cn } from "@/lib/utils"

function Section({
  className,
  ...props
}: React.ComponentProps<"section">) {
  return (
    <section
      data-slot="section"
      className={cn(
        "mx-auto w-full max-w-6xl scroll-mt-24 px-4 py-12 sm:px-6 md:py-20 lg:py-28",
        className
      )}
      {...props}
    />
  )
}

function SectionHeader({
  className,
  ...props
}: React.ComponentProps<"header">) {
  return (
    <header
      data-slot="section-header"
      className={cn(
        "mb-8 flex flex-col items-center gap-4 text-center md:mb-14",
        className
      )}
      {...props}
    />
  )
}

function SectionTitle({
  className,
  ...props
}: React.ComponentProps<"h2">) {
  return (
    <h2
      data-slot="section-title"
      className={cn(
        "max-w-2xl text-balance text-heading text-2xl sm:text-3xl md:text-4xl",
        className
      )}
      {...props}
    />
  )
}

function SectionDescription({
  className,
  ...props
}: React.ComponentProps<"p">) {
  return (
    <p
      data-slot="section-description"
      className={cn("max-w-lg text-balance text-description", className)}
      {...props}
    />
  )
}

export { Section, SectionDescription, SectionHeader, SectionTitle }

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { squircle } from "@/lib/squircle"
import { surfaceDepth } from "@/lib/surface-depth"
import { cn } from "@/lib/utils"
import {
  Section,
  SectionDescription,
  SectionHeader,
  SectionTitle,
} from "@/components/ui/section"

function getInitials(name: string) {
  return name
    .split(" ")
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase()
}

type TestimonialCardProps = React.ComponentProps<"article"> & {
  quote: string
  name: string
  role: string
  featured?: boolean
  avatar?: React.ReactNode
}

function TestimonialCard({
  quote,
  name,
  role,
  featured = false,
  avatar,
  className,
  ...props
}: TestimonialCardProps) {
  return (
    <article
      data-slot="testimonial-card"
      style={squircle}
      className={cn(
        "flex h-full flex-col rounded-squircle-lg border border-border bg-muted/30 p-2",
        className
      )}
      {...props}
    >
      <div
        style={squircle}
        className={cn(
          "relative flex flex-1 flex-col overflow-hidden rounded-squircle-md border p-6 sm:p-7",
          surfaceDepth("md"),
          featured
            ? "border-primary/35 bg-primary/5"
            : "border-border bg-card"
        )}
      >
        <div
          aria-hidden
          className="pointer-events-none absolute inset-0 bg-[radial-gradient(90%_80%_at_50%_100%,color-mix(in_srgb,var(--primary)_12%,transparent),transparent_65%)]"
        />
        <blockquote className="relative text-sm leading-relaxed sm:text-[15px]">
          &ldquo;{quote}&rdquo;
        </blockquote>
      </div>
      <footer className="flex items-center gap-3 px-3 pb-1 pt-3">
        {avatar ?? (
          <Avatar size="default">
            <AvatarFallback>{getInitials(name)}</AvatarFallback>
          </Avatar>
        )}
        <div className="min-w-0">
          <cite className="not-italic text-title text-sm">{name}</cite>
          <p className="truncate text-xs text-muted-foreground">{role}</p>
        </div>
      </footer>
    </article>
  )
}

type TestimonialsProps = Omit<React.ComponentProps<typeof Section>, "children"> & {
  title?: string
  description?: string
  children: React.ReactNode
}

function Testimonials({
  title,
  description,
  className,
  children,
  ...props
}: TestimonialsProps) {
  return (
    <Section data-slot="testimonials" className={className} {...props}>
      {title ? (
        <SectionHeader>
          <SectionTitle>{title}</SectionTitle>
          {description ? (
            <SectionDescription>{description}</SectionDescription>
          ) : null}
        </SectionHeader>
      ) : null}
      <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-3">{children}</div>
    </Section>
  )
}

export { TestimonialCard, Testimonials }
